-- =====================================================
-- Database Classify (MySQL / MariaDB)
-- Impor lewat phpMyAdmin: tab "Import" -> pilih file ini.
-- =====================================================
CREATE DATABASE IF NOT EXISTS classify CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE classify;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS chat, laporan_ob, peminjaman, ruang_kelas, admin, petugas_ob, dosen, mahasiswa;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE mahasiswa (
  nim      VARCHAR(20)  NOT NULL PRIMARY KEY,
  nama     VARCHAR(100) NOT NULL,
  fakultas VARCHAR(10)  NOT NULL,
  prodi    VARCHAR(80)  NOT NULL,
  kelas    VARCHAR(30)  NOT NULL
) ENGINE=InnoDB;

CREATE TABLE dosen (
  nisn     VARCHAR(20)  NOT NULL PRIMARY KEY,
  nama     VARCHAR(100) NOT NULL,
  fakultas VARCHAR(10)  NOT NULL
) ENGINE=InnoDB;

CREATE TABLE petugas_ob (
  id         VARCHAR(10)  NOT NULL PRIMARY KEY,
  nama       VARCHAR(100) NOT NULL,
  password   VARCHAR(255) NOT NULL,   -- hash bcrypt
  area_tugas VARCHAR(100)
) ENGINE=InnoDB;

CREATE TABLE admin (
  id       VARCHAR(10)  NOT NULL PRIMARY KEY,
  nama     VARCHAR(100) NOT NULL,
  password VARCHAR(255) NOT NULL,     -- hash bcrypt
  jabatan  VARCHAR(100)
) ENGINE=InnoDB;

CREATE TABLE ruang_kelas (
  kode      VARCHAR(15) NOT NULL PRIMARY KEY,
  gedung    VARCHAR(10) NOT NULL,
  lantai    TINYINT     NOT NULL,
  nomor     TINYINT     NOT NULL,
  kapasitas SMALLINT    NOT NULL DEFAULT 40
) ENGINE=InnoDB;

CREATE TABLE peminjaman (
  id           VARCHAR(30)  NOT NULL PRIMARY KEY,
  pemohon_role VARCHAR(20)  NOT NULL,
  pemohon_id   VARCHAR(20)  NOT NULL,
  pemohon_nama VARCHAR(100) NOT NULL,
  fakultas     VARCHAR(10)  NOT NULL,
  prodi        VARCHAR(80)  NOT NULL,
  kelas        VARCHAR(30)  NOT NULL,
  dosen        VARCHAR(100) NOT NULL,
  mata_kuliah  VARCHAR(120) NOT NULL,
  ruang        VARCHAR(15)  NOT NULL,
  tanggal      DATE         NOT NULL,
  sesi         VARCHAR(25)  NOT NULL,
  keperluan    VARCHAR(255),
  status       ENUM('Pending','Approved','Rejected') NOT NULL DEFAULT 'Pending',
  dibuat_pada  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_tanggal (tanggal),
  KEY idx_slot (ruang, tanggal, sesi),
  KEY idx_pemohon (pemohon_id),
  KEY idx_dosen (dosen),
  CONSTRAINT fk_peminjaman_ruang FOREIGN KEY (ruang) REFERENCES ruang_kelas(kode)
) ENGINE=InnoDB;

CREATE TABLE laporan_ob (
  id      VARCHAR(30)  NOT NULL PRIMARY KEY,
  pelapor VARCHAR(150) NOT NULL,
  lokasi  VARCHAR(100) NOT NULL,
  masalah VARCHAR(500) NOT NULL,
  status  VARCHAR(20)  NOT NULL DEFAULT 'Baru'
) ENGINE=InnoDB;

CREATE TABLE chat (
  id            INT AUTO_INCREMENT PRIMARY KEY,
  tab           VARCHAR(10)  NOT NULL,
  pengirim_id   VARCHAR(20)  NOT NULL,
  pengirim_nama VARCHAR(150) NOT NULL,
  pesan         VARCHAR(500) NOT NULL,
  waktu         VARCHAR(20)  NOT NULL
) ENGINE=InnoDB;

